[
  {
    "name": "create_function",
    "title": "Create Function",
    "description": "Define a new function at an address (Ghidra auto-detects bounds).",
    "inputSchema": {
      "additionalProperties": false,
      "properties": {
        "address": {
          "description": "Address (hex string, decimal, or symbol name).",
          "type": "string"
        },
        "database": {
          "type": "string",
          "description": "Database to target (stem ID from open_database / list_databases)."
        }
      },
      "required": [
        "address",
        "database"
      ],
      "type": "object"
    },
    "outputSchema": {
      "description": "Result of creating a function.",
      "properties": {
        "address": {
          "description": "Function start address (hex).",
          "type": "string"
        },
        "name": {
          "description": "Function name.",
          "type": "string"
        },
        "end": {
          "description": "Function end address (hex, exclusive).",
          "type": "string"
        },
        "size": {
          "description": "Function size in bytes.",
          "type": "integer"
        },
        "database": {
          "type": "string",
          "description": "Database identifier."
        }
      },
      "required": [
        "address",
        "name",
        "end",
        "size"
      ],
      "type": "object"
    },
    "annotations": {
      "readOnlyHint": false,
      "destructiveHint": false,
      "idempotentHint": true,
      "openWorldHint": false
    },
    "meta": {
      "fastmcp": {
        "tags": [
          "modification"
        ]
      }
    },
    "execution": {
      "taskSupport": "optional"
    }
  }
]

